#[cfg(test)]
mod tests {
    use super::*;

    fn valid(n: usize, deps: &[(usize, usize)], order: &[usize]) -> bool {
        let mut sorted = order.to_vec();
        sorted.sort();
        if sorted != (0..n).collect::<Vec<_>>() {
            return false;
        }
        let mut pos = vec![0; n];
        for (i, &t) in order.iter().enumerate() {
            pos[t] = i;
        }
        deps.iter().all(|&(a, b)| pos[b] < pos[a])
    }

    #[test]
    fn basic() {
        let deps = [(1, 0), (2, 0), (3, 1), (3, 2)];
        assert!(valid(4, &deps, &build_order(4, &deps)));
    }

    #[test]
    fn cycle() {
        assert_eq!(build_order(2, &[(0, 1), (1, 0)]), Vec::<usize>::new());
    }

    #[test]
    fn no_deps() {
        assert!(valid(3, &[], &build_order(3, &[])));
    }

    #[test]
    fn self_loop() {
        assert_eq!(build_order(3, &[(1, 0), (2, 2)]), Vec::<usize>::new());
    }

    #[test]
    fn long_chain() {
        let n = 5000;
        let deps: Vec<(usize, usize)> = (0..n - 1).map(|i| (i + 1, i)).collect();
        assert_eq!(build_order(n, &deps), (0..n).collect::<Vec<_>>());
    }
}
